220	fn handle_pre_tool_use() -> anyhow::Result<()> {
221	    let input = match read_stdin() {
222	        Ok(s) => s,
223	        Err(e) => {
224	            eprintln!("[codeflow] hook health-check: stdin read failed: {}", e);
225	            println!("{{}}");
226	            return Ok(());
227	        }
228	    };
229	
230	    let parsed: serde_json::Value = match serde_json::from_str(&input) {
231	        Ok(v) => v,
232	        Err(e) => {
233	            eprintln!(
234	                "[codeflow] hook health-check: invalid JSON from Claude Code: {}",
235	                e
236	            );
237	            println!("{{}}");
238	            return Ok(());
239	        }
240	    };
241	
242	    if !parsed.is_object() {
243	        eprintln!(
244	            "[codeflow] hook health-check: expected JSON object, got {}",
245	            parsed
246	        );
247	        println!("{{}}");
248	        return Ok(());
249	    }
250	
251	    let tool_name = match parsed.get("tool_name").and_then(|v| v.as_str()) {
252	        Some(name) => name,
253	        None => {
254	            println!("{{}}");
255	            return Ok(());
256	        }
257	    };
258	
259	    let tool_input = match parsed.get("tool_input") {
260	        Some(v) if v.is_object() => v,
261	        _ => {
262	            println!("{{}}");
263	            return Ok(());
264	        }
265	    };
266	
267	    // Log to session + dedup check (single connection, best-effort)
268	    let session_id = session_id();
269	    let file_path = codeflow_core::session::extract_file_path(tool_name, tool_input);
270	    let session_log = open_session_log(&session_id).ok();
271	
272	    if let Some(ref sl) = session_log {
273	        let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
274	        if let Ok(row_id) =
275	            sl.record_pre(tool_name, &tool_input_str, file_path.as_deref())
276	        {
277	            write_last_pre_id(tool_name, file_path.as_deref(), row_id);
278	        }
279	    }
280	
281	    match tool_name {
282	        "Bash" => {
283	            if let Some(command) = tool_input.get("command").and_then(|c| c.as_str()) {
284	                if should_wrap(command) {
285	                    let codeflow_bin = std::env::current_exe()
286	                        .map(|p| p.to_string_lossy().to_string())
287	                        .unwrap_or_else(|_| "codeflow".to_string());
288	                    let quoted_bin = shell_quote(&codeflow_bin);
289	                    let rewritten = format!("{} wrap {}", quoted_bin, command);
290	                    let response = serde_json::json!({
291	                        "tool_input": {
292	                            "command": rewritten
293	                        }
294	                    });
295	                    println!("{}", serde_json::to_string(&response)?);
296	                    return Ok(());
297	                }
298	            }
299	            println!("{{}}");
300	        }
301	        "Read" | "Grep" | "Glob" => {
302	            if let Some(ref session_log) = session_log {
303	                let window_secs = std::env::var("CODEFLOW_DEDUP_WINDOW_SECS")
304	                    .ok()
305	                    .and_then(|v| v.parse().ok());
306	                let dedup =
307	                    codeflow_core::read_dedup::ReadDedup::new(session_log, window_secs);
308	                let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
309	
310	                let result = match tool_name {
311	                    "Read" => {
312	                        if let Some(fp) = file_path.as_deref() {
313	                            dedup.check_read(fp)
314	                        } else {
315	                            codeflow_core::read_dedup::ReadDedupResult::Miss
316	                        }
317	                    }
318	                    "Grep" => dedup.check_grep(&tool_input_str),
319	                    "Glob" => dedup.check_glob(&tool_input_str),
320	                    _ => codeflow_core::read_dedup::ReadDedupResult::Miss,
321	                };
322	
323	                match result {
324	                    codeflow_core::read_dedup::ReadDedupResult::Hit {
325	                        context_message,
326	                        tokens_saved,
327	                    } => {
328	                        let response = serde_json::json!({
329	                            "additionalContext": context_message
330	                        });
331	                        println!("{}", serde_json::to_string(&response).unwrap_or_default());
332	
333	                        // Track savings
334	                        if tokens_saved > 0 {
335	                            if let Ok(tracking) =
336	                                codeflow_core::tracking::TrackingDb::open(&paths::db_path())
337	                            {
338	                                let _ = tracking.record(
339	                                    &codeflow_core::tracking::TrackingEvent {
340	                                        command: tool_name.to_string(),
341	                                        input_tokens: tokens_saved,
342	                                        output_tokens: 0,
343	                                        tokens_saved,
344	                                        layer:
345	                                            codeflow_core::tracking::SavingsLayer::ReadDedup,
346	                                        project: std::env::current_dir()
347	                                            .unwrap_or_default()
348	                                            .to_string_lossy()
349	                                            .to_string(),
350	                                        session_id: session_id.clone(),
351	                                    },
352	                                );
353	                            }
354	                        }
355	                        return Ok(());
356	                    }
357	                    codeflow_core::read_dedup::ReadDedupResult::Miss => {
358	                        println!("{{}}");
359	                    }
360	                }
361	            } else {
362	                println!("{{}}");
363	            }
364	        }
365	        _ => {
366	            println!("{{}}");
367	        }
368	    }
369	
370	    Ok(())
371	}
372	
373	fn handle_post_tool_use() -> anyhow::Result<()> {
374	    let input = match read_stdin() {
375	        Ok(s) => s,
376	        Err(_) => {
377	            println!("{{}}");
378	            return Ok(());
379	        }
380	    };
381	
382	    let parsed: serde_json::Value = serde_json::from_str(&input).unwrap_or_default();
383	    let tool_name = parsed.get("tool_name").and_then(|v| v.as_str());
384	    let tool_result = parsed
385	        .get("tool_result")
386	        .and_then(|v| v.as_str())
387	        .unwrap_or("");
388	
389	    if let Some(tn) = tool_name {
390	        if matches!(tn, "Read" | "Grep" | "Glob" | "Bash") {
391	            let file_path = parsed
392	                .get("tool_input")
393	                .and_then(|ti| codeflow_core::session::extract_file_path(tn, ti));
394	
395	            if let Some(row_id) = read_last_pre_id(tn, file_path.as_deref()) {
396	                let session_id = session_id();
397	                if let Ok(session_log) = open_session_log(&session_id) {
398	                    let capped = if tool_result.len() > 1_048_576 {
399	                        &tool_result[..1_048_576]
400	                    } else {
401	                        tool_result
402	                    };
403	                    let content_hash =
404	                        blake3::hash(capped.as_bytes()).to_hex().to_string();
405	                    let token_count = (tool_result.len() as i64 + 3) / 4;
406	
407	                    let mtime_ns =
408	                        file_path.as_deref().and_then(|fp| get_file_mtime_ns(fp));
409	
410	                    let _ = session_log.record_post(
411	                        row_id,
412	                        &content_hash,
413	                        token_count,
414	                        mtime_ns,
415	                    );
416	                }
417	            }
418	        }
419	    }
420	
421	    println!("{{}}");
422	    Ok(())
423	}
424	
425	fn open_session_log(
426	    session_id: &str,
427	) -> anyhow::Result<codeflow_core::session::SessionLog> {
428	    let db_path = paths::db_path();
429	    let data_dir = paths::data_dir();
430	    std::fs::create_dir_all(&data_dir)?;
431	    codeflow_core::session::SessionLog::open(&db_path, session_id)
432	}
433	
434	fn last_pre_id_path(tool_name: &str, file_path: Option<&str>) -> std::path::PathBuf {
435	    let key = format!(
436	        "{}:{}",
437	        tool_name,
438	        file_path.unwrap_or("_")
439	    );
440	    let hash = blake3::hash(key.as_bytes()).to_hex();
441	    paths::data_dir().join(format!("pre_id_{}", &hash[..16]))
442	}
443	
444	fn write_last_pre_id(tool_name: &str, file_path: Option<&str>, row_id: i64) {
445	    let _ = std::fs::create_dir_all(paths::data_dir());
446	    let _ = std::fs::write(last_pre_id_path(tool_name, file_path), row_id.to_string());
447	}
448	
449	fn read_last_pre_id(tool_name: &str, file_path: Option<&str>) -> Option<i64> {
450	    let path = last_pre_id_path(tool_name, file_path);
451	    let id = std::fs::read_to_string(&path).ok()?.trim().parse().ok();
452	    let _ = std::fs::remove_file(&path);
453	    id
454	}
455	
456	fn get_file_mtime_ns(path: &str) -> Option<i64> {
457	    let meta = std::fs::metadata(path).ok()?;
458	    let modified = meta.modified().ok()?;
459	    let duration = modified
460	        .duration_since(std::time::UNIX_EPOCH)
461	        .ok()?;
462	    Some(duration.as_nanos() as i64)
463	}
464	
465	fn should_wrap(command: &str) -> bool {
466	    let first_word = command.split_whitespace().next().unwrap_or("");
467	    let stem = std::path::Path::new(first_word)
468	        .file_stem()
469	        .and_then(|s| s.to_str())
470	        .unwrap_or(first_word);
471	    let wrappable = [
472	        "git", "npm", "npx", "pnpm", "yarn", "cargo", "pytest", "python",
473	        "tsc", "eslint", "ls", "find", "grep", "cat", "head", "tail",
474	        "docker", "kubectl", "go", "make", "pip", "ruff", "mypy", "vitest",
475	    ];
476	    wrappable.contains(&stem)
477	}
478	
479	fn shell_quote(s: &str) -> String {
480	    if s.contains(' ') || s.contains('\\') || s.contains('\'') || s.contains('"') {
481	        format!("'{}'", s.replace('\'', "'\\''"))
482	    } else {
483	        s.to_string()
484	    }
485	}
486	
487	fn read_stdin() -> anyhow::Result<String> {
488	    use std::io::Read;
489	    let mut buf = String::new();
490	    std::io::stdin().read_to_string(&mut buf)?;
491	    Ok(buf)
492	}
493	
494	fn session_id() -> String {
495	    std::env::var("CLAUDE_SESSION_ID")
496	        .or_else(|_| std::env::var("CODEFLOW_SESSION_ID"))
497	        .unwrap_or_else(|_| {
498	            #[cfg(unix)]
499	            let ppid = unsafe { libc::getppid() } as u32;
500	            #[cfg(not(unix))]
501	            let ppid = std::process::id();
502	            format!("local-{}", ppid)
503	        })
504	}
505

