254	fn stage_head_tail(text: &str, rule: &HeadTailRule) -> String {
255	    let lines: Vec<&str> = text.lines().collect();
256	    let total = lines.len();
257	    if total <= rule.head + rule.tail {
258	        return text.to_string();
259	    }
260	    let head_part: Vec<&str> = lines[..rule.head].to_vec();
261	    let tail_part: Vec<&str> = lines[total - rule.tail..].to_vec();
262	    let omitted = total - rule.head - rule.tail;
263	    let sep = rule.separator.replace("{omitted}", &omitted.to_string());
264	    format!("{}{}{}", head_part.join("\n"), sep, tail_part.join("\n"))
265	}
