1	use anyhow::Result;
2	use rusqlite::{params, Connection};
3	use serde::Serialize;
4	use std::path::Path;
5	use std::time::{SystemTime, UNIX_EPOCH};
6	
7	const RETENTION_DAYS: i64 = 90;
8	
9	pub struct TrackingDb {
10	    conn: Connection,
11	}
12	
13	#[derive(Debug, Clone, Copy, Serialize)]
14	pub enum SavingsLayer {
15	    Compression,
16	    Dedup,
17	    ReadDedup,
18	}
19	
20	impl SavingsLayer {
21	    fn as_str(&self) -> &'static str {
22	        match self {
23	            SavingsLayer::Compression => "compression",
24	            SavingsLayer::Dedup => "dedup",
25	            SavingsLayer::ReadDedup => "read_dedup",
26	        }
27	    }
28	}
29	
30	#[derive(Debug, Clone, Serialize)]
31	pub struct TrackingEvent {
32	    pub command: String,
33	    pub input_tokens: u64,
34	    pub output_tokens: u64,
35	    pub tokens_saved: u64,
36	    pub layer: SavingsLayer,
37	    pub project: String,
38	    pub session_id: String,
39	}
40	
41	#[derive(Debug, Clone, Serialize)]
42	pub struct Stats {
43	    pub total_input_tokens: u64,
44	    pub total_output_tokens: u64,
45	    pub total_saved: u64,
46	    pub savings_pct: f64,
47	    pub event_count: u64,
48	    pub top_commands: Vec<CommandStats>,
49	    pub by_layer: LayerStats,
50	}
51	
52	#[derive(Debug, Clone, Serialize)]
53	pub struct CommandStats {
54	    pub command: String,
55	    pub saved: u64,
56	    pub count: u64,
57	}
58	
59	#[derive(Debug, Clone, Serialize)]
60	pub struct LayerStats {
61	    pub compression_saved: u64,
62	    pub dedup_saved: u64,
63	    pub read_dedup_saved: u64,
64	}
65	
66	impl TrackingDb {
67	    pub fn open(db_path: &Path) -> Result<Self> {
68	        let conn = Connection::open(db_path)?;
69	        conn.execute_batch(
70	            "PRAGMA journal_mode=WAL;
71	             PRAGMA synchronous=NORMAL;
72	             PRAGMA busy_timeout=5000;"
73	        )?;
74	        conn.execute_batch(
75	            "CREATE TABLE IF NOT EXISTS tracking_events (
76	                id INTEGER PRIMARY KEY AUTOINCREMENT,
77	                timestamp INTEGER NOT NULL,
78	                command TEXT NOT NULL,
79	                input_tokens INTEGER NOT NULL,
80	                output_tokens INTEGER NOT NULL,
81	                tokens_saved INTEGER NOT NULL,
82	                layer TEXT NOT NULL,
83	                project TEXT NOT NULL,
84	                session_id TEXT NOT NULL
85	            );"
86	        )?;
87	        conn.execute_batch(
88	            "CREATE INDEX IF NOT EXISTS idx_tracking_timestamp
89	             ON tracking_events(timestamp);"
90	        )?;
91	        Ok(Self { conn })
92	    }
93	
94	    pub fn record(&self, event: &TrackingEvent) -> Result<()> {
95	        let now = now_secs();
96	        self.conn.execute(
97	            "INSERT INTO tracking_events
98	             (timestamp, command, input_tokens, output_tokens, tokens_saved,
99	              layer, project, session_id)
100	             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
101	            params![
102	                now as i64,
103	                event.command,
104	                event.input_tokens as i64,
105	                event.output_tokens as i64,
106	                event.tokens_saved as i64,
107	                event.layer.as_str(),
108	                event.project,
109	                event.session_id,
110	            ],
111	        )?;
112	        Ok(())
113	    }
114	
115	    pub fn stats(&self, days: Option<i64>) -> Result<Stats> {
116	        let days = days.unwrap_or(RETENTION_DAYS);
117	        let cutoff = now_secs() as i64 - (days * 86400);
118	
119	        let (total_input, total_output, total_saved, count): (i64, i64, i64, i64) = self
120	            .conn
121	            .query_row(
122	                "SELECT COALESCE(SUM(input_tokens),0), COALESCE(SUM(output_tokens),0),
123	                        COALESCE(SUM(tokens_saved),0), COUNT(*)
124	                 FROM tracking_events WHERE timestamp >= ?1",
125	                params![cutoff],
126	                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
127	            )?;
128	
129	        let savings_pct = if total_input > 0 {
130	            (total_saved as f64 / total_input as f64) * 100.0
131	        } else {
132	            0.0
133	        };
134	
135	        let mut top_stmt = self.conn.prepare(
136	            "SELECT command, SUM(tokens_saved) as saved, COUNT(*) as cnt
137	             FROM tracking_events WHERE timestamp >= ?1
138	             GROUP BY command ORDER BY saved DESC LIMIT 10",
