1	use anyhow::Result;
2	use serde::Serialize;
3	
4	use crate::session::SessionLog;
5	
6	pub struct WasteAnalyzer<'a> {
7	    session_log: &'a SessionLog,
8	}
9	
10	#[derive(Debug, Clone, Serialize)]
11	pub struct WasteReport {
12	    pub patterns: Vec<WastePattern>,
13	    pub total_wasted_tokens: u64,
14	    pub total_session_tokens: u64,
15	    pub waste_percentage: f64,
16	}
17	
18	#[derive(Debug, Clone, Serialize)]
19	#[serde(tag = "type")]
20	pub enum WastePattern {
21	    ReReadWaste {
22	        file_path: String,
23	        read_count: u64,
24	        redundant_count: u64,
25	        tokens_wasted: u64,
26	    },
27	    RedundantCommand {
28	        command_preview: String,
29	        run_count: u64,
30	        redundant_count: u64,
31	        tokens_wasted: u64,
32	    },
33	    FailedSearch {
34	        pattern_preview: String,
35	        attempt_count: u64,
36	    },
37	    GlobSpam {
38	        pattern_preview: String,
39	        run_count: u64,
40	        redundant_count: u64,
41	    },
42	    LargeUnusedRead {
43	        file_path: String,
44	        token_count: u64,
45	    },
46	}
47	
48	impl<'a> WasteAnalyzer<'a> {
49	    pub fn new(session_log: &'a SessionLog) -> Self {
50	        Self { session_log }
51	    }
52	
53	    pub fn analyze(&self) -> Result<WasteReport> {
54	        let entries = self.session_log.session_entries()?;
55	
56	        let total_session_tokens: u64 = entries
57	            .iter()
58	            .filter_map(|e| e.token_count)
59	            .map(|t| t as u64)
60	            .sum();
61	
62	        let mut patterns = Vec::new();
63	        let mut total_wasted: u64 = 0;
64	
65	        // 1. Re-read waste (files read >3x)
66	        let re_reads = self.detect_re_read_waste(&entries);
67	        for p in &re_reads {
68	            if let WastePattern::ReReadWaste { tokens_wasted, .. } = p {
69	                total_wasted += tokens_wasted;
70	            }
71	        }
72	        patterns.extend(re_reads);
73	
74	        // 2. Redundant commands (identical within 60s)
75	        let redundant = self.detect_redundant_commands(&entries);
76	        for p in &redundant {
77	            if let WastePattern::RedundantCommand { tokens_wasted, .. } = p {
78	                total_wasted += tokens_wasted;
79	            }
80	        }
81	        patterns.extend(redundant);
82	
83	        // 3. Failed searches
84	        patterns.extend(self.detect_failed_searches(&entries));
85	
86	        // 4. Glob spam
87	        patterns.extend(self.detect_glob_spam(&entries));
88	
89	        // 5. Large unused reads
90	        let unused = self.detect_large_unused_reads(&entries);
91	        for p in &unused {
92	            if let WastePattern::LargeUnusedRead { token_count, .. } = p {
93	                total_wasted += token_count;
94	            }
95	        }
96	        patterns.extend(unused);
97	
98	        let waste_percentage = if total_session_tokens > 0 {
99	            (total_wasted as f64 / total_session_tokens as f64) * 100.0
100	        } else {
101	            0.0
102	        };
103	
104	        Ok(WasteReport {
105	            patterns,
106	            total_wasted_tokens: total_wasted,
107	            total_session_tokens,
108	            waste_percentage,
109	        })
110	    }
111	
112	    fn detect_re_read_waste(
113	        &self,
114	        entries: &[crate::session::SessionEntry],
115	    ) -> Vec<WastePattern> {
116	        use std::collections::HashMap;
117	        let mut file_reads: HashMap<&str, Vec<i64>> = HashMap::new();
118	
119	        for e in entries {
120	            if e.tool_name == "Read" {
121	                if let Some(ref fp) = e.file_path {
122	                    file_reads
123	                        .entry(fp.as_str())
124	                        .or_default()
125	                        .push(e.token_count.unwrap_or(0));
126	                }
127	            }
128	        }
129	
130	        let mut results = Vec::new();
131	        for (path, tokens) in &file_reads {
132	            if tokens.len() > 3 {
133	                let avg_tokens = tokens.iter().sum::<i64>() / tokens.len() as i64;
134	                let redundant = tokens.len() as u64 - 1;
135	                results.push(WastePattern::ReReadWaste {
136	                    file_path: path.to_string(),
137	                    read_count: tokens.len() as u64,
138	                    redundant_count: redundant,
139	                    tokens_wasted: redundant * avg_tokens as u64,
140	                });
141	            }
142	        }
143	        results.sort_by(|a, b| {
144	            let wa = match a {
145	                WastePattern::ReReadWaste { tokens_wasted, .. } => *tokens_wasted,
146	                _ => 0,
147	            };
148	            let wb = match b {
149	                WastePattern::ReReadWaste { tokens_wasted, .. } => *tokens_wasted,
150	                _ => 0,
151	            };
152	            wb.cmp(&wa)
153	        });
154	        results
155	    }
156	
157	    fn detect_redundant_commands(
158	        &self,
159	        entries: &[crate::session::SessionEntry],
160	    ) -> Vec<WastePattern> {
161	        use std::collections::HashMap;
162	        let mut groups: HashMap<&str, Vec<(i64, i64)>> = HashMap::new();
163	
164	        for e in entries {
165	            groups
166	                .entry(&e.tool_input_hash)
167	                .or_default()
168	                .push((e.timestamp_ms, e.token_count.unwrap_or(0)));
169	        }
170	
171	        let mut results = Vec::new();
172	        for (_, group) in &groups {
173	            if group.len() < 2 {
174	                continue;
175	            }
176	            let mut redundant_count = 0u64;
177	            let mut tokens_wasted = 0u64;
178	            for i in 1..group.len() {
179	                let gap_secs = (group[i].0 - group[i - 1].0) / 1000;
180	                if gap_secs <= 60 {
181	                    redundant_count += 1;
182	                    tokens_wasted += group[i].1 as u64;
183	                }
184	            }
185	            if redundant_count > 0 {
186	                // Find preview from entries
187	                let hash = groups.keys().find(|k| {
188	                    groups[*k].len() == group.len()
189	                        && groups[*k][0].0 == group[0].0
190	                });
191	                let preview = entries
192	                    .iter()
193	                    .find(|e| {
194	                        hash.map_or(false, |h| e.tool_input_hash == *h)
195	                    })
196	                    .map(|e| {
197	                        let s = &e.tool_input_json;
198	                        if s.len() > 60 {
199	                            format!("{}…", s.chars().take(60).collect::<String>())
200	                        } else {
201	                            s.clone()
202	                        }
203	                    })
204	                    .unwrap_or_default();
205	
206	                results.push(WastePattern::RedundantCommand {
207	                    command_preview: preview,
208	                    run_count: group.len() as u64,
209	                    redundant_count,
210	                    tokens_wasted,
211	                });
212	            }
213	        }
214	        results.sort_by(|a, b| {
215	            let wa = match a {
216	                WastePattern::RedundantCommand { tokens_wasted, .. } => *tokens_wasted,
217	                _ => 0,
218	            };
219	            let wb = match b {
220	                WastePattern::RedundantCommand { tokens_wasted, .. } => *tokens_wasted,
221	                _ => 0,
222	            };
223	            wb.cmp(&wa)
224	        });
225	        results
226	    }
227	
228	    fn detect_failed_searches(
229	        &self,
230	        entries: &[crate::session::SessionEntry],
231	    ) -> Vec<WastePattern> {
232	        let mut results = Vec::new();
233	        use std::collections::HashMap;
234	        let mut grep_results: HashMap<String, u64> = HashMap::new();
235	
236	        for e in entries {
237	            if e.tool_name == "Grep" && e.token_count.unwrap_or(1) == 0 {
238	                let preview = if e.tool_input_json.len() > 60 {
239	                    format!("{}…", &e.tool_input_json[..60])
240	                } else {
241	                    e.tool_input_json.clone()
242	                };
243	                *grep_results.entry(preview).or_insert(0) += 1;
244	            }
245	        }
246	
247	        for (preview, count) in grep_results {
248	            results.push(WastePattern::FailedSearch {
249	                pattern_preview: preview,
250	                attempt_count: count,
251	            });
252	        }
253	        results
254	    }
255	
256	    fn detect_glob_spam(
257	        &self,
258	        entries: &[crate::session::SessionEntry],
259	    ) -> Vec<WastePattern> {
260	        use std::collections::HashMap;
261	        let mut glob_counts: HashMap<&str, u64> = HashMap::new();
262	
263	        for e in entries {
264	            if e.tool_name == "Glob" {
265	                *glob_counts.entry(&e.tool_input_hash).or_insert(0) += 1;
266	            }
267	        }
268	
269	        let mut results = Vec::new();
270	        for (hash, count) in &glob_counts {
271	            if *count > 2 {
272	                let preview = entries
273	                    .iter()
274	                    .find(|e| e.tool_name == "Glob" && &e.tool_input_hash.as_str() == hash)
275	                    .map(|e| {
276	                        if e.tool_input_json.len() > 60 {
277	                            format!("{}…", &e.tool_input_json[..60])
278	                        } else {
279	                            e.tool_input_json.clone()
280	                        }
281	                    })
282	                    .unwrap_or_default();
283	                results.push(WastePattern::GlobSpam {
284	                    pattern_preview: preview,
285	                    run_count: *count,
