28	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
29	pub enum Complexity {
30	    Low,
31	    Medium,
32	    High,
33	}
34	
35	pub struct RoutingInput {
36	    pub command: String,
37	    pub context_tokens: u64,
38	    pub file_extensions: Vec<String>,
39	    pub session_event_count: u64,
40	}
41	
42	pub struct RoutingDecision {
43	    pub tier: ModelTier,
44	    pub complexity: Complexity,
45	    pub score: f64,
46	    pub reason: String,
47	    pub estimated_savings_pct: f64,
48	}
49	
50	pub fn classify(input: &RoutingInput) -> RoutingDecision {
51	    let mut score: f64 = 0.5;
52	    let mut reasons = Vec::new();
53	
54	    // Command complexity
55	    let cmd_score = command_complexity(&input.command);
56	    score += cmd_score;
57	    if cmd_score.abs() > 0.05 {
58	        reasons.push(format!(
59	            "command '{}' complexity {:.2}",
60	            first_word(&input.command),
61	            cmd_score
62	        ));
63	    }
64	
65	    // Context size
66	    let ctx_score = context_complexity(input.context_tokens);
67	    score += ctx_score;
68	    if ctx_score.abs() > 0.05 {
69	        reasons.push(format!("context {}K tokens {:.2}", input.context_tokens / 1000, ctx_score));
70	    }
71	
72	    // File type complexity
73	    let ext_score = file_extension_complexity(&input.file_extensions);
74	    score += ext_score;
75	    if ext_score.abs() > 0.05 {
76	        reasons.push(format!("file types {:.2}", ext_score));
77	    }
