36	pub fn run(config: SyncConfig) -> Result<()> {
37	    let db_path = paths::db_path();
38	    if !db_path.exists() {
39	        println!("No events to sync.");
40	        return Ok(());
41	    }
42	
43	    let event_buf = EventBuffer::open(&db_path)?;
44	    let pending = event_buf.pending_count()?;
45	    println!("Pending events: {}", pending);
46	
47	    if pending == 0 {
48	        println!("Nothing to sync.");
49	        return Ok(());
50	    }
51	
52	    let mut circuit_failures: u32 = 0;
53	    let mut circuit_open_until: Option<Instant> = None;
54	
55	    loop {
56	        if let Some(open_until) = circuit_open_until {
57	            if Instant::now() < open_until {
58	                if config.one_shot {
59	                    eprintln!("Circuit breaker open. Retry later.");
60	                    return Ok(());
61	                }
62	                let remaining = open_until - Instant::now();
63	                tracing::warn!(secs = remaining.as_secs(), "circuit breaker open, waiting");
64	                std::thread::sleep(remaining.min(Duration::from_secs(10)));
65	                continue;
66	            }
67	            circuit_open_until = None;
68	            circuit_failures = 0;
69	        }
70	
71	        let batch = event_buf.consume_batch(BATCH_MAX_EVENTS)?;
72	        if batch.is_empty() {
73	            if config.one_shot {
74	                println!("All events synced.");
75	                return Ok(());
76	            }
77	            std::thread::sleep(BATCH_FLUSH_INTERVAL);
78	            continue;
79	        }
80	
81	        let ids: Vec<i64> = batch.iter().map(|(id, _)| *id).collect();
82	        let events: Vec<proto::Event> = batch.into_iter().map(|(_, e)| e).collect();
83	
84	        let payload = encode_batch(&events, &config)?;
85	
86	        if payload.len() > BATCH_MAX_BYTES {
87	            tracing::warn!(
88	                size = payload.len(),
89	                "batch exceeds max bytes, splitting not implemented — sending anyway"
90	            );
91	        }
92	
93	        match send_batch(&config, &payload) {
94	            Ok(()) => {
95	                event_buf.mark_consumed(&ids)?;
96	                event_buf.purge_consumed()?;
97	                circuit_failures = 0;
98	                tracing::info!(count = ids.len(), "batch synced");
99	                println!("  Synced {} events", ids.len());
100	            }
101	            Err(e) => {
102	                circuit_failures += 1;
103	                tracing::error!(err = %e, failures = circuit_failures, "sync failed");
104	                eprintln!("  Sync failed: {} (attempt {}/{})", e, circuit_failures, CIRCUIT_BREAKER_THRESHOLD);
105	
106	                if circuit_failures >= CIRCUIT_BREAKER_THRESHOLD {
107	                    circuit_open_until = Some(Instant::now() + CIRCUIT_BREAKER_COOLDOWN);
108	                    tracing::warn!("circuit breaker opened");
109	                    eprintln!("  Circuit breaker opened — will retry in {}s", CIRCUIT_BREAKER_COOLDOWN.as_secs());
110	                }
111	
112	                if config.one_shot {
113	                    return Err(e);
114	                }
115	
116	                let backoff = Duration::from_secs(2u64.pow(circuit_failures.min(MAX_RETRIES)));
117	                std::thread::sleep(backoff);
118	            }
119	        }
120	    }
121	}
