package api

import (
	"log/slog"
	"net/http"
)

type RouterOption func(*handler)

func WithPublisher(p EventPublisher) RouterOption {
	return func(h *handler) { h.publisher = p }
}

func NewRouter(store Storage, logger *slog.Logger, opts ...RouterOption) http.Handler {
	apiMux := http.NewServeMux()

	h := &handler{store: store, hub: newWSHub(), logger: logger}
	for _, opt := range opts {
		opt(h)
	}

	apiMux.HandleFunc("POST /v1/events", h.handleIngestEvents)
	apiMux.HandleFunc("GET /v1/overview", h.handleOverview)
	apiMux.HandleFunc("GET /v1/projects", h.handleListProjects)
	apiMux.HandleFunc("GET /v1/projects/{id}/stats", h.handleProjectStats)
	apiMux.HandleFunc("GET /v1/savings/trend", h.handleSavingsTrend)
	apiMux.HandleFunc("GET /v1/waste", h.handleWasteReport)
	apiMux.HandleFunc("GET /v1/waste/projects", h.handleProjectWasteScores)
	apiMux.HandleFunc("GET /v1/security/alerts", h.handleSecurityAlerts)
	apiMux.HandleFunc("GET /v1/billing/status", h.handleBillingStatus)
	apiMux.HandleFunc("POST /v1/billing/checkout", h.handleCreateCheckout)
	apiMux.HandleFunc("POST /v1/billing/webhook", h.handleStripeWebhook)
	apiMux.HandleFunc("GET /v1/export/csv", h.handleExportCSV)
	apiMux.HandleFunc("GET /v1/roi", h.handleROISummary)
	apiMux.HandleFunc("GET /v1/ws", h.handleWebSocket)

	rl := newRateLimiter()

	var wrapped http.Handler = apiMux
	wrapped = withRateLimit(rl)(wrapped)
	wrapped = withTenantAuth(wrapped)
	wrapped = withCORS(wrapped)

	root := http.NewServeMux()
	root.HandleFunc("GET /healthz", handleHealthz)
	root.Handle("/", wrapped)

	return withLogging(logger, root)
}

func handleHealthz(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(`{"status":"ok"}`))
}

func withLogging(logger *slog.Logger, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		logger.Info("request",
			"method", r.Method,
			"path", r.URL.Path,
			"remote", r.RemoteAddr,
		)
		next.ServeHTTP(w, r)
	})
}

package main

import (
	"context"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/codeflow-dev/codeflow/cloud/internal/api"
	"github.com/codeflow-dev/codeflow/cloud/internal/clickhouse"
	"github.com/codeflow-dev/codeflow/cloud/internal/natsutil"
)

func main() {
	logger := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo}))
	slog.SetDefault(logger)

	chDSN := envOr("CLICKHOUSE_DSN", "clickhouse://localhost:9000/codeflow")
	listenAddr := envOr("LISTEN_ADDR", ":8080")
	natsURL := os.Getenv("NATS_URL")

	ch, err := clickhouse.New(chDSN)
	if err != nil {
		slog.Error("failed to connect to clickhouse", "error", err)
		os.Exit(1)
	}
	defer ch.Close()
	slog.Info("connected to clickhouse", "dsn", chDSN)

	var opts []api.RouterOption

	if natsURL != "" {
		pub, err := natsutil.NewPublisher(natsURL)
		if err != nil {
			slog.Error("failed to connect to nats", "error", err)
			os.Exit(1)
		}
		defer pub.Close()

		if err := pub.EnsureStream(context.Background()); err != nil {
			slog.Error("failed to ensure nats stream", "error", err)
			os.Exit(1)
		}

		opts = append(opts, api.WithPublisher(pub))
		slog.Info("nats enabled — events will be published to jetstream", "url", natsURL)
	} else {
		slog.Info("nats not configured — events will be inserted directly to clickhouse")
	}

	handler := api.NewRouter(ch, logger, opts...)

	srv := &http.Server{
		Addr:         listenAddr,
		Handler:      handler,
		ReadTimeout:  30 * time.Second,
		WriteTimeout: 30 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	go func() {
		slog.Info("ingest API listening", "addr", listenAddr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			slog.Error("server error", "error", err)
			os.Exit(1)
		}
	}()

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	slog.Info("shutting down...")
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(ctx); err != nil {
		slog.Error("shutdown error", "error", err)
	}
	slog.Info("server stopped")
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

package api

import (
	"compress/gzip"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"time"

	"github.com/codeflow-dev/codeflow/cloud/internal/clickhouse"
	"google.golang.org/protobuf/proto"

	pb "github.com/codeflow-dev/codeflow/cloud/proto"
)

type EventPublisher interface {
	Publish(ctx context.Context, tenantID string, data []byte) error
}

type handler struct {
	store     Storage
	publisher EventPublisher
	hub       *wsHub
	logger    *slog.Logger
}

func (h *handler) handleIngestEvents(w http.ResponseWriter, r *http.Request) {
	tenantID := tenantFromCtx(r)

	var reader io.Reader = r.Body
	if r.Header.Get("Content-Encoding") == "gzip" {
		gz, err := gzip.NewReader(r.Body)
		if err != nil {
			http.Error(w, "invalid gzip", http.StatusBadRequest)
			return
		}
		defer gz.Close()
		reader = gz
	}

	body, err := io.ReadAll(io.LimitReader(reader, 10*1024*1024))
	if err != nil {
		http.Error(w, "read error", http.StatusBadRequest)
		return
	}

	var batch pb.EventBatch
	if err := proto.Unmarshal(body, &batch); err != nil {
		http.Error(w, fmt.Sprintf("invalid protobuf: %v", err), http.StatusBadRequest)
		return
	}

	if h.publisher != nil {
		protoData, err := proto.Marshal(&batch)
		if err != nil {
			http.Error(w, "marshal error", http.StatusInternalServerError)
			return
		}
		if err := h.publisher.Publish(r.Context(), tenantID, protoData); err != nil {
			h.logger.Error("nats publish failed", "error", err, "count", len(batch.Events))
			http.Error(w, "publish failed", http.StatusInternalServerError)
			return
		}
	} else {
		rows := batchToRows(tenantID, &batch)
		if err := h.store.InsertEvents(r.Context(), rows); err != nil {
			h.logger.Error("clickhouse insert failed", "error", err, "count", len(rows))
			http.Error(w, "insert failed", http.StatusInternalServerError)
			return
		}
	}

	h.logger.Info("events ingested",
		"tenant", tenantID,
		"count", len(batch.Events),
		"cli_version", batch.CliVersion,
		"via", func() string { if h.publisher != nil { return "nats" }; return "direct" }(),
	)

	if h.hub != nil {
		var saved uint64
		for _, ev := range batch.Events {
			if ev.Compression != nil {
				saved += ev.Compression.TokensSaved
			}
			if ev.Dedup != nil {
				saved += ev.Dedup.TokensSaved
			}
		}
		h.hub.Broadcast(tenantID, LiveMetrics{
			TokensSavedToday: saved,
			EventsToday:      uint64(len(batch.Events)),
			Timestamp:         time.Now().UnixMilli(),
		})
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusAccepted)
	json.NewEncoder(w).Encode(map[string]any{
		"accepted": len(batch.Events),
	})
}

func batchToRows(tenantID string, batch *pb.EventBatch) []clickhouse.EventRow {
	rows := make([]clickhouse.EventRow, 0, len(batch.Events))
	for _, ev := range batch.Events {
		row := clickhouse.EventRow{
			EventID:    ev.Id,
			TenantID:   tenantID,
			Timestamp:  time.UnixMilli(ev.TimestampMs),
			SessionID:  ev.SessionId,
			ProjectDir: ev.ProjectDir,
			Command:    ev.Command,
			CLIVersion: batch.CliVersion,
			MachineID:  batch.MachineId,
		}
		if ev.Compression != nil {
			row.EventType = "compression"
			row.InputBytes = ev.Compression.InputBytes
			row.OutputBytes = ev.Compression.OutputBytes
			row.InputTokens = ev.Compression.InputTokens
			row.OutputTokens = ev.Compression.OutputTokens
			row.TokensSaved = ev.Compression.TokensSaved
			row.FilterName = ev.Compression.FilterName
			row.CompressionLevel = ev.Compression.CompressionLevel
			row.LatencyMs = ev.Compression.LatencyMs
		}
		if ev.Dedup != nil {
			row.EventType = "dedup"
			row.ContentHash = ev.Dedup.ContentHash
			row.CacheHit = ev.Dedup.CacheHit
			row.TokensSaved = ev.Dedup.TokensSaved
			row.LatencyMs = ev.Dedup.LatencyMs
		}
		rows = append(rows, row)
	}
	return rows
}

func (h *handler) handleOverview(w http.ResponseWriter, r *http.Request) {
	tenantID := tenantFromCtx(r)

	stats, err := h.store.GetOverview(r.Context(), tenantID)
	if err != nil {
		h.logger.Error("overview query failed", "error", err)
		http.Error(w, "query failed", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(stats)
}

