import { authkitMiddleware } from "@workos-inc/authkit-nextjs";

export default authkitMiddleware({
  middlewareAuth: {
    enabled: true,
    unauthenticatedPaths: ["/auth/callback"],
  },
});

export const config = {
  matcher: [
    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)",
  ],
};

package api

import (
	"bytes"
	"compress/gzip"
	"encoding/json"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	pb "github.com/codeflow-dev/codeflow/cloud/proto"
	"google.golang.org/protobuf/proto"
)

func newTestRouter(store Storage) http.Handler {
	logger := slog.New(slog.NewTextHandler(io.Discard, nil))
	return NewRouter(store, logger)
}

func makeBatch(events ...*pb.Event) *pb.EventBatch {
	return &pb.EventBatch{
		CliVersion: "0.1.0-test",
		MachineId:  "test-machine",
		Events:     events,
	}
}

func compressionEvent(id, cmd string, input, saved uint64) *pb.Event {
	return &pb.Event{
		Id:          id,
		TimestampMs: time.Now().UnixMilli(),
		SessionId:   "sess-1",
		ProjectDir:  "/home/user/project",
		Command:     cmd,
		Compression: &pb.CompressionEvent{
			InputTokens:  input,
			OutputTokens: input - saved,
			TokensSaved:  saved,
			FilterName:   "git-diff",
			LatencyMs:    1.2,
		},
	}
}

func dedupEvent(id, cmd string, saved uint64) *pb.Event {
	return &pb.Event{
		Id:          id,
		TimestampMs: time.Now().UnixMilli(),
		SessionId:   "sess-1",
		ProjectDir:  "/home/user/project",
		Command:     cmd,
		Dedup: &pb.DedupEvent{
			ContentHash: "abc123",
			CacheHit:    true,
			TokensSaved: saved,
			LatencyMs:   0.3,
		},
	}
}

func marshalGzip(batch *pb.EventBatch) ([]byte, error) {
	data, err := proto.Marshal(batch)
	if err != nil {
		return nil, err
	}
	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	if _, err := gz.Write(data); err != nil {
		return nil, err
	}
	if err := gz.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func TestIngestEvents_GzipProtobuf(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	batch := makeBatch(
		compressionEvent("e1", "git diff", 1000, 400),
		dedupEvent("e2", "cat README.md", 200),
	)

	body, err := marshalGzip(batch)
	if err != nil {
		t.Fatal(err)
	}

	req := httptest.NewRequest("POST", "/v1/events", bytes.NewReader(body))
	req.Header.Set("Content-Type", "application/x-protobuf")
	req.Header.Set("Content-Encoding", "gzip")
	req.Header.Set("X-Tenant-ID", "tenant-1")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusAccepted {
		t.Fatalf("expected 202, got %d: %s", w.Code, w.Body.String())
	}

	var resp map[string]any
	json.NewDecoder(w.Body).Decode(&resp)
	if accepted, _ := resp["accepted"].(float64); accepted != 2 {
		t.Fatalf("expected 2 accepted, got %v", resp["accepted"])
	}

	if store.eventCount() != 2 {
		t.Fatalf("expected 2 stored events, got %d", store.eventCount())
	}
}

func TestIngestEvents_PlainProtobuf(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	batch := makeBatch(compressionEvent("e1", "cargo test", 500, 100))
	data, _ := proto.Marshal(batch)

	req := httptest.NewRequest("POST", "/v1/events", bytes.NewReader(data))
	req.Header.Set("Content-Type", "application/x-protobuf")
	req.Header.Set("X-Tenant-ID", "tenant-1")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusAccepted {
		t.Fatalf("expected 202, got %d: %s", w.Code, w.Body.String())
	}

	if store.eventCount() != 1 {
		t.Fatalf("expected 1 stored event, got %d", store.eventCount())
	}
}

func TestIngestEvents_InvalidProtobuf(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	req := httptest.NewRequest("POST", "/v1/events", bytes.NewReader([]byte("not protobuf")))
	req.Header.Set("Content-Type", "application/x-protobuf")
	req.Header.Set("X-Tenant-ID", "tenant-1")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusBadRequest {
		t.Fatalf("expected 400, got %d", w.Code)
	}

	if store.eventCount() != 0 {
		t.Fatalf("expected 0 stored events, got %d", store.eventCount())
	}
}

func TestIngestEvents_InvalidGzip(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	req := httptest.NewRequest("POST", "/v1/events", bytes.NewReader([]byte("not gzip")))
	req.Header.Set("Content-Type", "application/x-protobuf")
	req.Header.Set("Content-Encoding", "gzip")
	req.Header.Set("X-Tenant-ID", "tenant-1")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusBadRequest {
		t.Fatalf("expected 400, got %d", w.Code)
	}
}

func TestIngestEvents_EmptyBatch(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	batch := makeBatch()
	data, _ := proto.Marshal(batch)

	req := httptest.NewRequest("POST", "/v1/events", bytes.NewReader(data))
	req.Header.Set("Content-Type", "application/x-protobuf")
	req.Header.Set("X-Tenant-ID", "tenant-1")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusAccepted {
		t.Fatalf("expected 202, got %d: %s", w.Code, w.Body.String())
	}

	var resp map[string]any
	json.NewDecoder(w.Body).Decode(&resp)
	if accepted, _ := resp["accepted"].(float64); accepted != 0 {
		t.Fatalf("expected 0 accepted, got %v", resp["accepted"])
	}
}

func TestIngestEvents_TenantFromJWT(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	batch := makeBatch(compressionEvent("e1", "git status", 300, 50))
	data, _ := proto.Marshal(batch)

	// JWT with {"tenant_id":"jwt-tenant"} payload
	token := "eyJhbGciOiJIUzI1NiJ9.eyJ0ZW5hbnRfaWQiOiJqd3QtdGVuYW50In0.sig"

	req := httptest.NewRequest("POST", "/v1/events", bytes.NewReader(data))
	req.Header.Set("Content-Type", "application/x-protobuf")
	req.Header.Set("Authorization", "Bearer "+token)

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusAccepted {
		t.Fatalf("expected 202, got %d: %s", w.Code, w.Body.String())
	}

	if store.eventCount() != 1 {
		t.Fatal("expected 1 event")
	}
	if tid := store.tenantOfEvent(0); tid != "jwt-tenant" {
		t.Fatalf("expected tenant 'jwt-tenant', got '%s'", tid)
	}
}

func TestIngestEvents_DefaultTenant(t *testing.T) {
	store := newFakeStorage()
	router := newTestRouter(store)

	batch := makeBatch(compressionEvent("e1", "ls", 100, 20))
	data, _ := proto.Marshal(batch)

	req := httptest.NewRequest("POST", "/v1/events", bytes.NewReader(data))
	req.Header.Set("Content-Type", "application/x-protobuf")

	w := httptest.NewRecorder()
	router.ServeHTTP(w, req)

	if w.Code != http.StatusAccepted {
		t.Fatalf("expected 202, got %d: %s", w.Code, w.Body.String())
	}

	if tid := store.tenantOfEvent(0); tid != "default" {
		t.Fatalf("expected tenant 'default', got '%s'", tid)
	}
}

